/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// Service class to run the update Nat3040 report number
/// </summary>
class METNat3040RegisterUpdateService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// MPJ_5013_ExciseRegister
    /// Checks if run in batch or not.
    /// </summary>
    public void processOperation()
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        NumberSeq               num;
        Num                     number;

        num     = NumberSeq::newGetNum(VendParameters::numRefNat30Number());
        number  = num.num();

        update_recordset metExciseRegisterEntry 
            setting Nat3040ReportNumber = number
            where metExciseRegisterEntry.CustomerExempt      == NoYes::No
            &&    metExciseRegisterEntry.Nat3040ReportNumber == '';

        num.used();

    
    }
